from __future__ import annotations

from typing import Any

from models import Document, Principal


def normalize(value: str) -> str:
    return value.strip().lower()


def edge_key(tenant_id: str, owner_user_id: str) -> str:
    return f"{normalize(tenant_id)}::{normalize(owner_user_id)}"


class AccessGraph:
    def __init__(self) -> None:
        self._edges: dict[str, set[str]] = {}

    def grant(self, tenant_id: str, user_id: str, doc_id: str) -> None:
        key = edge_key(tenant_id, user_id)
        self._edges.setdefault(key, set())
        self._edges[key].add(normalize(doc_id))

    def revoke(self, tenant_id: str, user_id: str, doc_id: str) -> bool:
        key = edge_key(tenant_id, user_id)
        value = normalize(doc_id)
        if key not in self._edges or value not in self._edges[key]:
            return False
        self._edges[key].remove(value)
        return True

    def has(self, tenant_id: str, user_id: str, doc_id: str) -> bool:
        key = edge_key(tenant_id, user_id)
        value = normalize(doc_id)
        return value in self._edges.get(key, set())

    def list_docs(self, tenant_id: str, user_id: str) -> list[str]:
        key = edge_key(tenant_id, user_id)
        return sorted(self._edges.get(key, set()))

    def clear(self) -> None:
        self._edges.clear()

    def snapshot(self) -> dict[str, list[str]]:
        return {k: sorted(v) for k, v in self._edges.items()}

    def count(self) -> int:
        return sum(len(v) for v in self._edges.values())

    def seed_owner_edges(self, docs: list[Document]) -> None:
        for doc in docs:
            self.grant(doc.tenant_id, doc.owner_user_id, doc.doc_id)

    def users_for_doc(self, tenant_id: str, doc_id: str) -> list[str]:
        tenant = normalize(tenant_id)
        needle = normalize(doc_id)
        result: list[str] = []
        for key, docs in self._edges.items():
            t, user = key.split("::", 1)
            if t == tenant and needle in docs:
                result.append(user)
        return sorted(result)


def can_access_via_graph(graph: AccessGraph, principal: Principal, doc: Document) -> bool:
    if principal.normalized_tenant() != doc.normalized_tenant():
        return False
    if principal.is_admin():
        return True
    return graph.has(doc.tenant_id, principal.user_id, doc.doc_id)


def access_report(graph: AccessGraph, principal: Principal, doc: Document) -> dict[str, Any]:
    return {
        "principal": principal.to_dict(),
        "doc_id": doc.doc_id,
        "tenant_match": principal.normalized_tenant() == doc.normalized_tenant(),
        "graph_access": graph.has(doc.tenant_id, principal.user_id, doc.doc_id),
        "allowed": can_access_via_graph(graph, principal, doc),
    }


def bulk_report(graph: AccessGraph, principal: Principal, docs: list[Document]) -> list[dict[str, Any]]:
    return [access_report(graph, principal, doc) for doc in docs]


def copy_graph(source: AccessGraph) -> AccessGraph:
    target = AccessGraph()
    for key, values in source.snapshot().items():
        tenant, user = key.split("::", 1)
        for doc_id in values:
            target.grant(tenant, user, doc_id)
    return target


def tenant_edge_count(graph: AccessGraph, tenant_id: str) -> int:
    tenant = normalize(tenant_id)
    count = 0
    for key, docs in graph.snapshot().items():
        t, _user = key.split("::", 1)
        if t == tenant:
            count += len(docs)
    return count


def owner_edge_count(graph: AccessGraph, tenant_id: str, user_id: str) -> int:
    return len(graph.list_docs(tenant_id, user_id))


def edge_density(graph: AccessGraph, principals: int) -> float:
    if principals <= 0:
        return 0.0
    return round(graph.count() / float(principals), 3)


def orphan_docs(graph: AccessGraph, docs: list[Document]) -> list[str]:
    result: list[str] = []
    for doc in docs:
        owners = graph.users_for_doc(doc.tenant_id, doc.doc_id)
        if not owners:
            result.append(doc.doc_id)
    return sorted(result)

