from __future__ import annotations

from typing import Any


class AuditLog:
    def __init__(self) -> None:
        self._rows: list[dict[str, Any]] = []

    def add(self, event: str, details: dict[str, Any]) -> None:
        self._rows.append({"event": event, "details": dict(details)})

    def list(self) -> list[dict[str, Any]]:
        return [{"event": row["event"], "details": dict(row["details"])} for row in self._rows]

    def count(self) -> int:
        return len(self._rows)

    def clear(self) -> None:
        self._rows.clear()

    def summary(self) -> dict[str, int]:
        out: dict[str, int] = {}
        for row in self._rows:
            key = str(row["event"]).strip().lower()
            out[key] = out.get(key, 0) + 1
        return out

    def by_event(self, event: str) -> list[dict[str, Any]]:
        needle = event.strip().lower()
        return [row for row in self.list() if str(row["event"]).strip().lower() == needle]

    def has(self, event: str) -> bool:
        return len(self.by_event(event)) > 0

    def last(self) -> dict[str, Any] | None:
        if not self._rows:
            return None
        row = self._rows[-1]
        return {"event": row["event"], "details": dict(row["details"])}

    def remove_first(self, event: str) -> bool:
        needle = event.strip().lower()
        for idx, row in enumerate(self._rows):
            if str(row["event"]).strip().lower() == needle:
                del self._rows[idx]
                return True
        return False

    def request_ids(self) -> list[str]:
        values: list[str] = []
        for row in self._rows:
            rid = str(row["details"].get("request_id", "")).strip()
            if rid:
                values.append(rid)
        return values

    def unique_request_ids(self) -> list[str]:
        return sorted(set(self.request_ids()))

    def compact(self) -> list[tuple[str, str]]:
        return [(str(row["event"]), str(row["details"].get("request_id", ""))) for row in self._rows]

