from __future__ import annotations

from typing import Any

from models import Document, Principal


def can_read(principal: Principal, doc: Document) -> bool:
    if principal.is_admin() and principal.normalized_tenant() == doc.normalized_tenant():
        return True
    return principal.normalized_user() == doc.normalized_owner() and principal.normalized_tenant() == doc.normalized_tenant()


def can_list(principal: Principal, tenant_id: str) -> bool:
    tenant = tenant_id.strip().lower()
    if principal.normalized_tenant() != tenant:
        return False
    return principal.normalized_role() in {"admin", "member"}


def decision(principal: Principal, doc: Document | None = None, tenant_id: str = "") -> dict[str, Any]:
    if doc is not None:
        return {"ok": can_read(principal, doc), "reason": "allowed" if can_read(principal, doc) else "forbidden"}
    if tenant_id:
        return {"ok": can_list(principal, tenant_id), "reason": "allowed" if can_list(principal, tenant_id) else "forbidden"}
    return {"ok": False, "reason": "bad_request"}


def redact(doc: Document) -> dict[str, Any]:
    return {"doc_id": doc.doc_id, "tenant_id": doc.tenant_id, "owner_user_id": doc.owner_user_id, "title": doc.title}


def role_caps(role: str) -> dict[str, bool]:
    key = role.strip().lower()
    return {"read_own": key in {"member", "admin"}, "read_all_tenant": key == "admin"}


def can_manage(principal: Principal, tenant_id: str) -> bool:
    return principal.normalized_role() == "admin" and principal.normalized_tenant() == tenant_id.strip().lower()


def tenant_match(principal: Principal, doc: Document) -> bool:
    return principal.normalized_tenant() == doc.normalized_tenant()


def owner_match(principal: Principal, doc: Document) -> bool:
    return principal.normalized_user() == doc.normalized_owner()


def explain(principal: Principal, doc: Document) -> dict[str, Any]:
    return {
        "tenant_match": tenant_match(principal, doc),
        "owner_match": owner_match(principal, doc),
        "is_admin": principal.is_admin(),
        "allowed": can_read(principal, doc),
    }


def redact_many(docs: list[Document]) -> list[dict[str, Any]]:
    return [redact(doc) for doc in docs]


def policy_name(principal: Principal) -> str:
    return "tenant_admin" if principal.is_admin() else "tenant_member"

