class CacheIndex:
    def __init__(self) -> None:
        self._docs: dict[str, dict[str, Any]] = {}
        self._hits = 0
        self._misses = 0

    def set(self, doc_id: str, row: dict[str, Any]) -> None:
        self._docs[doc_id.strip().lower()] = dict(row)

    def get(self, doc_id: str) -> dict[str, Any] | None:
        key = doc_id.strip().lower()
        row = self._docs.get(key)
        if row is None:
            self._misses += 1
            return None
        self._hits += 1
        return dict(row)

    def invalidate(self, doc_id: str) -> bool:
        key = doc_id.strip().lower()
        if key not in self._docs:
            return False
        del self._docs[key]
        return True

    def clear(self) -> None:
        self._docs.clear()
        self._hits = 0
        self._misses = 0

    def stats(self) -> dict[str, int]:
        return {"size": len(self._docs), "hits": self._hits, "misses": self._misses}

    def snapshot(self) -> dict[str, dict[str, Any]]:
        return {k: dict(v) for k, v in self._docs.items()}

    def warm(self, rows: list[dict[str, Any]]) -> None:
        for row in rows:
            key = str(row.get("doc_id", "")).strip().lower()
            if key:
                self.set(key, row)

    def keys(self) -> list[str]:
        return sorted(self._docs.keys())

    def size(self) -> int:
        return len(self._docs)

    def has(self, doc_id: str) -> bool:
        return doc_id.strip().lower() in self._docs

    def remove_tenant(self, tenant_id: str) -> int:
        needle = tenant_id.strip().lower()
        keys = [key for key, row in self._docs.items() if str(row.get("tenant_id", "")).strip().lower() == needle]
        for key in keys:
            del self._docs[key]
        return len(keys)

    def hit_ratio(self) -> float:
        total = self._hits + self._misses
        if total == 0:
            return 0.0
        return round(self._hits / float(total), 3)

