class Metrics:
    def __init__(self) -> None:
        self._counts: dict[str, int] = {}

    def inc(self, key: str) -> None:
        name = key.strip().lower()
        self._counts[name] = self._counts.get(name, 0) + 1

    def get(self, key: str) -> int:
        return int(self._counts.get(key.strip().lower(), 0))

    def snapshot(self) -> dict[str, int]:
        return dict(self._counts)

    def clear(self) -> None:
        self._counts.clear()

    def keys(self) -> list[str]:
        return sorted(self._counts.keys())

    def total(self) -> int:
        return sum(self._counts.values())

    def top(self, n: int = 5) -> list[tuple[str, int]]:
        return sorted(self._counts.items(), key=lambda kv: kv[1], reverse=True)[: max(0, int(n))]

    def has(self, key: str) -> bool:
        return key.strip().lower() in self._counts

    def remove(self, key: str) -> bool:
        name = key.strip().lower()
        if name not in self._counts:
            return False
        del self._counts[name]
        return True

    def merge(self, other: "Metrics") -> None:
        for key, value in other.snapshot().items():
            self._counts[key] = self._counts.get(key, 0) + int(value)

    def reset(self, key: str) -> None:
        self._counts[key.strip().lower()] = 0

    def describe(self) -> dict[str, object]:
        return {"total": self.total(), "keys": self.keys(), "top": self.top(3)}

    def copy(self) -> "Metrics":
        m = Metrics()
        for key, value in self._counts.items():
            m._counts[key] = int(value)
        return m

    def prefix(self, name: str) -> dict[str, int]:
        needle = name.strip().lower()
        return {k: v for k, v in self._counts.items() if k.startswith(needle)}


def combine(metrics_list: list["Metrics"]) -> "Metrics":
    merged = Metrics()
    for metric in metrics_list:
        merged.merge(metric)
    return merged

