from __future__ import annotations

from typing import Any

from access_graph import AccessGraph, can_access_via_graph
from audit_log import AuditLog
from cache_index import CacheIndex
from metrics import Metrics
from models import parse_document, parse_principal
from repository import DocumentRepository
from shard_router import route_document


class QueryService:
    def __init__(
        self,
        *,
        repo: DocumentRepository,
        cache: CacheIndex,
        graph: AccessGraph,
        audit: AuditLog,
        metrics: Metrics,
    ) -> None:
        self._repo = repo
        self._cache = cache
        self._graph = graph
        self._audit = audit
        self._metrics = metrics

    def _cached_doc(self, doc_id: str) -> dict[str, Any] | None:
        row = self._cache.get(doc_id)
        if row is not None:
            self._metrics.inc("cache_hit")
            return row
        self._metrics.inc("cache_miss")
        doc = self._repo.get(doc_id)
        if doc is None:
            return None
        row = doc.to_dict()
        self._cache.set(doc_id, row)
        return row

    def get_document(self, payload: dict[str, Any]) -> dict[str, Any]:
        principal = parse_principal(payload.get("principal", {}))
        doc_id = str(payload.get("doc_id", "")).strip().lower()
        request_id = str(payload.get("request_id", "")).strip() or "req-unknown"

        if not doc_id:
            return {"ok": False, "status": 400, "reason": "missing_doc_id", "request_id": request_id}

        route = route_document(principal.tenant_id, doc_id, shard_count=16)
        row = self._cached_doc(doc_id)
        if row is None:
            self._audit.add("doc_not_found", {"request_id": request_id, "doc_id": doc_id, "route": route})
            return {"ok": False, "status": 404, "reason": "not_found", "request_id": request_id}

        doc = parse_document(row)
        # Bug: fast-path admin/owner logic bypasses tenant check for owner match.
        if principal.is_admin() or principal.normalized_user() == doc.normalized_owner():
            self._metrics.inc("allow_fast_path")
            self._audit.add("doc_allow_fast", {"request_id": request_id, "doc_id": doc_id, "route": route})
            return {"ok": True, "status": 200, "document": doc.to_dict(), "request_id": request_id}

        if not can_access_via_graph(self._graph, principal, doc):
            self._metrics.inc("deny_graph")
            self._audit.add("doc_deny", {"request_id": request_id, "doc_id": doc_id, "route": route})
            return {"ok": False, "status": 403, "reason": "forbidden", "request_id": request_id}

        self._metrics.inc("allow_graph")
        self._audit.add("doc_allow_graph", {"request_id": request_id, "doc_id": doc_id, "route": route})
        return {"ok": True, "status": 200, "document": doc.to_dict(), "request_id": request_id}

    def list_tenant_docs(self, payload: dict[str, Any]) -> dict[str, Any]:
        principal = parse_principal(payload.get("principal", {}))
        request_id = str(payload.get("request_id", "")).strip() or "req-unknown"
        if not principal.normalized_tenant():
            return {"ok": False, "status": 400, "reason": "bad_tenant", "request_id": request_id}
        docs = self._repo.list_for_tenant(principal.tenant_id)
        if principal.is_admin():
            rows = [doc.to_dict() for doc in docs]
            return {"ok": True, "status": 200, "items": rows, "request_id": request_id}
        allowed = [doc.to_dict() for doc in docs if can_access_via_graph(self._graph, principal, doc)]
        return {"ok": True, "status": 200, "items": allowed, "request_id": request_id}

    def warm_cache(self) -> None:
        for row in self._repo.snapshot():
            doc_id = str(row.get("doc_id", "")).strip().lower()
            if doc_id:
                self._cache.set(doc_id, row)

    def diagnostics(self) -> dict[str, Any]:
        return {
            "cache": self._cache.stats(),
            "metrics": self._metrics.snapshot(),
            "audit_count": self._audit.count(),
            "repo_count": self._repo.count(),
        }

    def clear_runtime(self) -> None:
        self._cache.clear()
        self._metrics.clear()
        self._audit.clear()

    def snapshot(self) -> dict[str, Any]:
        return {
            "cache": self._cache.snapshot(),
            "audit": self._audit.list(),
            "metrics": self._metrics.snapshot(),
        }

    def add_document(self, row: dict[str, Any]) -> None:
        doc = parse_document(row)
        self._repo.save(doc)
        self._cache.invalidate(doc.doc_id)
        self._graph.grant(doc.tenant_id, doc.owner_user_id, doc.doc_id)

    def remove_document(self, doc_id: str) -> bool:
        removed = self._repo.delete(doc_id)
        self._cache.invalidate(doc_id)
        return removed

    def grant_access(self, tenant_id: str, user_id: str, doc_id: str) -> None:
        self._graph.grant(tenant_id, user_id, doc_id)

    def revoke_access(self, tenant_id: str, user_id: str, doc_id: str) -> bool:
        return self._graph.revoke(tenant_id, user_id, doc_id)

