from typing import Any

from models import Document, parse_document


class DocumentRepository:
    def __init__(self) -> None:
        self._rows: dict[str, dict[str, Any]] = {}

    def save(self, doc: Document) -> None:
        self._rows[doc.normalized_doc_id()] = doc.to_dict()

    def get(self, doc_id: str) -> Document | None:
        row = self._rows.get(doc_id.strip().lower())
        if row is None:
            return None
        return parse_document(dict(row))

    def list_for_tenant(self, tenant_id: str) -> list[Document]:
        tenant = tenant_id.strip().lower()
        result: list[Document] = []
        for row in self._rows.values():
            if str(row.get("tenant_id", "")).strip().lower() == tenant:
                result.append(parse_document(dict(row)))
        return result

    def seed(self, rows: list[dict[str, Any]]) -> None:
        for row in rows:
            self.save(parse_document(row))

    def count(self) -> int:
        return len(self._rows)

    def snapshot(self) -> list[dict[str, Any]]:
        return [dict(v) for v in self._rows.values()]

    def clear(self) -> None:
        self._rows.clear()

    def exists(self, doc_id: str) -> bool:
        return self.get(doc_id) is not None

    def list_ids(self) -> list[str]:
        return sorted(self._rows.keys())

    def by_owner(self, owner: str) -> list[Document]:
        needle = owner.strip().lower()
        return [
            parse_document(dict(row))
            for row in self._rows.values()
            if str(row.get("owner_user_id", "")).strip().lower() == needle
        ]

    def delete(self, doc_id: str) -> bool:
        key = doc_id.strip().lower()
        if key not in self._rows:
            return False
        del self._rows[key]
        return True

    def tenant_count(self, tenant_id: str) -> int:
        return len(self.list_for_tenant(tenant_id))

    def owner_count(self, owner: str) -> int:
        return len(self.by_owner(owner))

    def tenant_ids(self) -> list[str]:
        values = {str(row.get("tenant_id", "")).strip().lower() for row in self._rows.values()}
        return sorted([v for v in values if v])

    def stats(self) -> dict[str, Any]:
        return {"count": self.count(), "tenant_ids": self.tenant_ids(), "ids": self.list_ids()}

